package com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.api;
import com.hrcoresystem.hrcore_api.common.response.ApiResponse; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.application.dto.IncidentDtos.*; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.application.service.*; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.domain.model.IncidentModels.*; import jakarta.validation.Valid; import java.nio.charset.StandardCharsets; import java.nio.file.Files; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.http.*; import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;
@RestController @RequestMapping("/api/incidents") public class IncidentController {private final IncidentService service;private final IncidentAttachmentService files;public IncidentController(IncidentService s,IncidentAttachmentService f){service=s;files=f;}
 @PostMapping @PreAuthorize("hasAuthority('incidents.create')") public ApiResponse<IncidentResponse> create(@Valid @RequestBody Create r){return ApiResponse.success("Incidencia registrada correctamente",service.create(r));}
 @GetMapping @PreAuthorize("hasAuthority('incidents.list')") public ApiResponse<Page<IncidentResponse>> list(@RequestParam(required=false) UUID employeeId,@RequestParam(required=false) UUID employmentPeriodId,@RequestParam(required=false) Type incidentType,@RequestParam(required=false) Severity severity,@RequestParam(required=false) Status status,@PageableDefault(size=25) Pageable page){return ApiResponse.success("Incidencias consultadas correctamente",service.list(employeeId,employmentPeriodId,incidentType,severity,status,page));}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('incidents.detail')") public ApiResponse<IncidentResponse> detail(@PathVariable UUID id){return ApiResponse.success("Incidencia consultada correctamente",service.detail(id));}
 @GetMapping("/{id}/history") @PreAuthorize("hasAuthority('incidents.history.read')") public ApiResponse<List<HistoryResponse>> history(@PathVariable UUID id){return ApiResponse.success("Historial consultado correctamente",service.history(id));}
 @PostMapping(value="/{id}/attachments",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasAuthority('incidents.attachments.upload')") public ApiResponse<AttachmentResponse> upload(@PathVariable UUID id,@RequestParam(required=false) AttachmentType attachmentType,@RequestParam(required=false) String description,@RequestPart("file") MultipartFile file){return ApiResponse.success("Evidencia cargada correctamente",files.upload(id,attachmentType,description,file));}
 @GetMapping("/{id}/attachments") @PreAuthorize("hasAuthority('incidents.attachments.list')") public ApiResponse<Page<AttachmentResponse>> attachments(@PathVariable UUID id,@PageableDefault(size=25) Pageable page){return ApiResponse.success("Evidencias consultadas correctamente",files.list(id,page));}
 @GetMapping("/{id}/attachments/{attachmentId}/download") @PreAuthorize("hasAuthority('incidents.attachments.download')") public ResponseEntity<StreamingResponseBody> download(@PathVariable UUID id,@PathVariable UUID attachmentId){var result=files.download(id,attachmentId);StreamingResponseBody body=out->{try{Files.copy(result.path(),out);}finally{result.cleanup();}};return ResponseEntity.ok().contentType(MediaType.parseMediaType(result.mimeType())).contentLength(result.size()).cacheControl(CacheControl.noStore()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(result.filename(),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").body(body);}
 @PatchMapping("/{id}/assign") @PreAuthorize("hasAuthority('incidents.assign')") public ApiResponse<IncidentResponse> assign(@PathVariable UUID id,@Valid @RequestBody Assign r){return ApiResponse.success("Responsable asignado correctamente",service.assign(id,r.assignedTo()));}
 @PostMapping("/{id}/start-review") @PreAuthorize("hasAuthority('incidents.review')") public ApiResponse<IncidentResponse> review(@PathVariable UUID id){return ApiResponse.success("Revisión iniciada correctamente",service.startReview(id));}
 @PatchMapping("/{id}/resolve") @PreAuthorize("hasAuthority('incidents.resolve')") public ApiResponse<IncidentResponse> resolve(@PathVariable UUID id,@Valid @RequestBody Resolution r){return ApiResponse.success("Incidencia resuelta correctamente",service.resolve(id,r.comment()));}
 @PatchMapping("/{id}/employee-response") @PreAuthorize("hasAuthority('incidents.update')") public ApiResponse<IncidentResponse> employeeResponse(@PathVariable UUID id,@Valid @RequestBody EmployeeResponse r){return ApiResponse.success("Respuesta del empleado registrada correctamente",service.employeeResponse(id,r.response()));}
 @PatchMapping("/{id}/close") @PreAuthorize("hasAuthority('incidents.close')") public ApiResponse<IncidentResponse> close(@PathVariable UUID id,@RequestBody(required=false) Resolution r){return ApiResponse.success("Incidencia cerrada correctamente",service.close(id,r==null?null:r.comment()));}
 @PatchMapping("/{id}/cancel") @PreAuthorize("hasAuthority('incidents.cancel')") public ApiResponse<IncidentResponse> cancel(@PathVariable UUID id,@RequestBody(required=false) Resolution r){return ApiResponse.success("Incidencia cancelada correctamente",service.cancel(id,r==null?null:r.comment()));}
 @PostMapping("/{id}/actions") @PreAuthorize("hasAuthority('incidents.actions.create')") public ApiResponse<ActionResponse> action(@PathVariable UUID id,@Valid @RequestBody ActionCreate r){return ApiResponse.success("Acción registrada correctamente",service.addAction(id,r));}
 @GetMapping("/{id}/actions") @PreAuthorize("hasAuthority('incidents.actions.list')") public ApiResponse<List<ActionResponse>> actions(@PathVariable UUID id){return ApiResponse.success("Acciones consultadas correctamente",service.actions(id));}
 @PatchMapping("/{id}/actions/{actionId}/start") @PreAuthorize("hasAuthority('incidents.actions.update')") public ApiResponse<ActionResponse> startAction(@PathVariable UUID id,@PathVariable UUID actionId){return ApiResponse.success("Acción iniciada correctamente",service.actionStatus(id,actionId,ActionStatus.IN_PROGRESS));}
 @PatchMapping("/{id}/actions/{actionId}/complete") @PreAuthorize("hasAuthority('incidents.actions.update')") public ApiResponse<ActionResponse> completeAction(@PathVariable UUID id,@PathVariable UUID actionId){return ApiResponse.success("Acción completada correctamente",service.actionStatus(id,actionId,ActionStatus.COMPLETED));}
 @PatchMapping("/{id}/actions/{actionId}/cancel") @PreAuthorize("hasAuthority('incidents.actions.update')") public ApiResponse<ActionResponse> cancelAction(@PathVariable UUID id,@PathVariable UUID actionId){return ApiResponse.success("Acción cancelada correctamente",service.actionStatus(id,actionId,ActionStatus.CANCELLED));}}
